package pillar.templateregistry.upgrade
enum class UpgradeState{announce,stage,dual_publish,cutover,retire,paused,rolled_back}
data class Approval(val actor:String,val secondary:String?=null){ fun dual()=secondary!=null && secondary!=actor }
class UpgradeStateMachine { private val allowed=mapOf(UpgradeState.announce to setOf(UpgradeState.stage,UpgradeState.paused), UpgradeState.stage to setOf(UpgradeState.dual_publish,UpgradeState.paused,UpgradeState.rolled_back), UpgradeState.dual_publish to setOf(UpgradeState.cutover,UpgradeState.paused,UpgradeState.rolled_back), UpgradeState.cutover to setOf(UpgradeState.retire,UpgradeState.paused), UpgradeState.paused to setOf(UpgradeState.stage,UpgradeState.dual_publish,UpgradeState.rolled_back), UpgradeState.retire to emptySet(), UpgradeState.rolled_back to emptySet()); fun transition(from:UpgradeState,to:UpgradeState,approval:Approval,production:Boolean=false):UpgradeState { if(to !in (allowed[from] ?: emptySet())) error("blocked transition $from->$to"); if(production && to in setOf(UpgradeState.cutover,UpgradeState.retire,UpgradeState.dual_publish) && !approval.dual()) error("dual-control required"); return to } }
